// ---------------------------------------------------------------- press-reported cyberattacks (ransomware.live)
// ransomware.live's recentcyberattacks list pairs a victim organisation with the press report that disclosed the
// attack. Its two-letter country field is free text: in the 100 rows read on 2026-10-19, eleven did not hold the
// ISO 3166-1 code of the victim's country. Five were name abbreviations that are no ISO code (PO Poland, KO Korea,
// SW Sweden, TU Turkey, DN Denmark); one was UK, the usual shorthand for the United Kingdom, written for Ukraine;
// five collide with another country's code (CH for Chile, IR Ireland, IS Israel, PR Portugal, BG Bangladesh).
// normalizeCyberattacks() reads the field as a set of candidate countries and settles it with the victim's domain,
// the outlet's domain and the headline; a row that stays ambiguous is kept and left unplaced. This part has no
// imports and touches nothing outside itself, so /api/ransomware imports it on its own and the collector joins it
// like any other part.

// ISO 3166-1 alpha-2 codes of the dashboard atlas (lib/num2iso.json, plus XK) with the short English names newsrooms
// use; alternates after '/'. Generated by build/ccnames.py from pycountry with the formal forms rewritten.
const CA_NAMES = new Map("AD:Andorra|AE:United Arab Emirates|AF:Afghanistan|AG:Antigua and Barbuda|AI:Anguilla|AL:Albania|AM:Armenia|AO:Angola|AQ:Antarctica|AR:Argentina|AS:American Samoa|AT:Austria|AU:Australia|AW:Aruba|AX:Aland Islands|AZ:Azerbaijan|BA:Bosnia and Herzegovina|BB:Barbados|BD:Bangladesh|BE:Belgium|BF:Burkina Faso|BG:Bulgaria|BH:Bahrain|BI:Burundi|BJ:Benin|BL:Saint Barthelemy|BM:Bermuda|BN:Brunei|BO:Bolivia|BQ:Caribbean Netherlands|BR:Brazil|BS:Bahamas|BT:Bhutan|BV:Bouvet Island|BW:Botswana|BY:Belarus|BZ:Belize|CA:Canada|CC:Cocos Islands|CD:DR Congo/Democratic Republic of the Congo|CF:Central African Republic|CG:Republic of the Congo/Congo|CH:Switzerland|CI:Ivory Coast/Cote d'Ivoire|CK:Cook Islands|CL:Chile|CM:Cameroon|CN:China|CO:Colombia|CR:Costa Rica|CU:Cuba|CV:Cape Verde/Cabo Verde|CW:Curacao|CX:Christmas Island|CY:Cyprus|CZ:Czechia/Czech Republic|DE:Germany|DJ:Djibouti|DK:Denmark|DM:Dominica|DO:Dominican Republic|DZ:Algeria|EC:Ecuador|EE:Estonia|EG:Egypt|EH:Western Sahara|ER:Eritrea|ES:Spain|ET:Ethiopia|FI:Finland|FJ:Fiji|FK:Falkland Islands|FM:Micronesia|FO:Faroe Islands|FR:France|GA:Gabon|GB:United Kingdom/Britain|GD:Grenada|GE:Georgia|GF:French Guiana|GG:Guernsey|GH:Ghana|GI:Gibraltar|GL:Greenland|GM:Gambia|GN:Guinea|GP:Guadeloupe|GQ:Equatorial Guinea|GR:Greece|GS:South Georgia and the South Sandwich Islands|GT:Guatemala|GU:Guam|GW:Guinea-Bissau|GY:Guyana|HK:Hong Kong|HM:Heard and McDonald Islands|HN:Honduras|HR:Croatia|HT:Haiti|HU:Hungary|ID:Indonesia|IE:Ireland|IL:Israel|IM:Isle of Man|IN:India|IO:British Indian Ocean Territory|IQ:Iraq|IR:Iran|IS:Iceland|IT:Italy|JE:Jersey|JM:Jamaica|JO:Jordan|JP:Japan|KE:Kenya|KG:Kyrgyzstan|KH:Cambodia|KI:Kiribati|KM:Comoros|KN:Saint Kitts and Nevis|KP:North Korea|KR:South Korea|KW:Kuwait|KY:Cayman Islands|KZ:Kazakhstan|LA:Laos|LB:Lebanon|LC:Saint Lucia|LI:Liechtenstein|LK:Sri Lanka|LR:Liberia|LS:Lesotho|LT:Lithuania|LU:Luxembourg|LV:Latvia|LY:Libya|MA:Morocco|MC:Monaco|MD:Moldova|ME:Montenegro|MF:Saint Martin|MG:Madagascar|MH:Marshall Islands|MK:North Macedonia|ML:Mali|MM:Myanmar/Burma|MN:Mongolia|MO:Macao|MP:Northern Mariana Islands|MQ:Martinique|MR:Mauritania|MS:Montserrat|MT:Malta|MU:Mauritius|MV:Maldives|MW:Malawi|MX:Mexico|MY:Malaysia|MZ:Mozambique|NA:Namibia|NC:New Caledonia|NE:Niger|NF:Norfolk Island|NG:Nigeria|NI:Nicaragua|NL:Netherlands|NO:Norway|NP:Nepal|NR:Nauru|NU:Niue|NZ:New Zealand|OM:Oman|PA:Panama|PE:Peru|PF:French Polynesia|PG:Papua New Guinea|PH:Philippines|PK:Pakistan|PL:Poland|PM:Saint Pierre and Miquelon|PN:Pitcairn Islands|PR:Puerto Rico|PS:Palestine|PT:Portugal|PW:Palau|PY:Paraguay|QA:Qatar|RE:Reunion|RO:Romania|RS:Serbia|RU:Russia|RW:Rwanda|SA:Saudi Arabia|SB:Solomon Islands|SC:Seychelles|SD:Sudan|SE:Sweden|SG:Singapore|SH:Saint Helena|SI:Slovenia|SJ:Svalbard and Jan Mayen|SK:Slovakia|SL:Sierra Leone|SM:San Marino|SN:Senegal|SO:Somalia|SR:Suriname|SS:South Sudan|ST:Sao Tome and Principe|SV:El Salvador|SX:Sint Maarten|SY:Syria|SZ:Eswatini/Swaziland|TC:Turks and Caicos Islands|TD:Chad|TF:French Southern Territories|TG:Togo|TH:Thailand|TJ:Tajikistan|TK:Tokelau|TL:Timor-Leste/East Timor|TM:Turkmenistan|TN:Tunisia|TO:Tonga|TR:Turkey/Turkiye|TT:Trinidad and Tobago|TV:Tuvalu|TW:Taiwan|TZ:Tanzania|UA:Ukraine|UG:Uganda|UM:US Minor Outlying Islands|US:United States|UY:Uruguay|UZ:Uzbekistan|VA:Vatican City|VC:Saint Vincent and the Grenadines|VE:Venezuela|VG:British Virgin Islands|VI:US Virgin Islands|VN:Vietnam|VU:Vanuatu|WF:Wallis and Futuna|WS:Samoa|XK:Kosovo|YE:Yemen|YT:Mayotte|ZA:South Africa|ZM:Zambia|ZW:Zimbabwe".split('|').map((s) => [s.slice(0, 2), s.slice(3).split('/')]));

// Feed codes seen to carry more than their ISO meaning, or none. Each list is the full set of readings; a code that
// is absent here and valid in ISO reads as itself. Evidence for every entry: the 2026-10-19 sample described above,
// and for AU a later collector copy the same day, which coded Loxone (loxone.com, an Austrian firm, reported by
// borncity.com) AU, the code for Australia.
const CA_ALIAS = { PO: ['PL'], KO: ['KR'], SW: ['SE'], TU: ['TR'], DN: ['DK'], UK: ['GB', 'UA'],
  CH: ['CH', 'CL'], IR: ['IR', 'IE'], IS: ['IS', 'IL'], PR: ['PR', 'PT'], BG: ['BG', 'BD'], AU: ['AU', 'AT'] };

// Country-code TLDs registered for general use, which say nothing about where the registrant is: the list Google
// Search Central treats as generic (.ad .as .bz .cc .cd .co .dj .fm .io .la .me .ms .nu .sc .sr .su .tv .tk .ws),
// plus .ai, which Google added in 2023.
const CA_GENERIC = new Set('ad as bz cc cd co dj fm io la me ms nu sc sr su tv tk ws ai'.split(' '));

// Headline names for the countries an ambiguous code can stand for (English, plus the Swiss national languages and
// the German names of Australia and Austria; 'sterreich' matches Oesterreich with or without the umlaut).
const CA_TITLE = {
  CH: /\b(switzerland|swiss|schweiz\w*|suisse|svizzera)\b/i, CL: /\bchile(an)?\b/i,
  IR: /\biran(ian)?\b/i, IE: /(?<!northern )\b(ireland|irish)\b/i,
  IS: /\biceland(ic)?\b/i, IL: /\bisrael(i)?\b/i,
  PR: /\bpuerto ric(o|an)\b/i, PT: /\bportug(al|uese)\b/i,
  BG: /\bbulgaria(n)?\b/i, BD: /\bbangladesh(i)?\b/i,
  GB: /\b(united kingdom|u\.k\.|uk|britain|british|england|scotland|scottish|northern ireland)(?![\w.])/i, UA: /\bukrain(e|ian)\b/i,
  AU: /\baustralia(n|ns)?\b|\baustralien\b/i, AT: /\baustria(n)?\b|sterreich/i,
};

// Country of a host name from its last label: a two-letter country TLD (uk is GB), or US for .gov, .mil and .edu,
// which only US bodies can register. Generic-use and unassigned TLDs give ''.
export function ccOfHost(host) {
  const h = String(host || '').trim().toLowerCase().replace(/\.+$/, '');
  const i = h.lastIndexOf('.');
  if (i < 1) return '';
  const tld = h.slice(i + 1);
  if (tld === 'uk') return 'GB';
  if (tld === 'gov' || tld === 'mil' || tld === 'edu') return 'US';
  if (tld.length !== 2 || CA_GENERIC.has(tld)) return '';
  const cc = tld.toUpperCase();
  return CA_NAMES.has(cc) ? cc : '';
}

const caFold = (s) => s.normalize('NFD').replace(/\p{Mn}/gu, '').toUpperCase();
// True when a two-letter code reads as an abbreviation of a country's English name: the first letter starts a word of
// the name and the second follows inside that word (DN Denmark, KO South Korea), or the letters are the initials of
// two consecutive words (UK United Kingdom, SA South Africa).
export function ccAbbrev(code, cc) {
  const k = String(code || '').toUpperCase();
  if (!/^[A-Z]{2}$/.test(k)) return false;
  for (const name of CA_NAMES.get(cc) || []) {
    const w = caFold(name).split(/[^A-Z]+/).filter((x) => x && x !== 'OF' && x !== 'THE' && x !== 'AND');
    for (let i = 0; i < w.length; i++) {
      if (w[i][0] !== k[0]) continue;
      if (w[i].indexOf(k[1], 1) > 0) return true;
      if (i + 1 < w.length && w[i + 1][0] === k[1]) return true;
    }
  }
  return false;
}

// Settles one row's country. Order: the victim's domain confirms one reading of the code; the outlet's domain or a
// headline that names exactly one reading picks between several; a victim domain whose country the code abbreviates
// overrides the code's ISO meaning (DE written for Denmark on a .dk domain); then the code's single reading; with no
// usable code, the victim's domain, or an outlet whose country the code abbreviates. Anything else stays unplaced.
export function placeCyberattack(code, victimHost, outletHost, title) {
  const raw = String(code || '').trim().toUpperCase();
  const cand = CA_ALIAS[raw] || (CA_NAMES.has(raw) ? [raw] : []);
  const v = ccOfHost(victimHost), o = ccOfHost(outletHost);
  if (v && cand.includes(v)) return { cc: v, basis: 'code+domain' };
  if (cand.length > 1) {
    if (o && cand.includes(o)) return { cc: o, basis: 'code+outlet' };
    const named = cand.filter((c) => CA_TITLE[c] && CA_TITLE[c].test(String(title || '')));
    if (named.length === 1) return { cc: named[0], basis: 'code+title' };
  }
  if (v && ccAbbrev(raw, v)) return { cc: v, basis: 'domain-abbrev' };
  if (cand.length === 1) return { cc: cand[0], basis: CA_ALIAS[raw] ? 'code-alias' : 'code' };
  if (!cand.length && v) return { cc: v, basis: 'domain' };
  if (!cand.length && o && ccAbbrev(raw, o)) return { cc: o, basis: 'outlet-abbrev' };
  return { cc: '', basis: 'unresolved', candidates: cand };
}

const caDay = (s) => { const d = String(s || '').slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : ''; };
const caHost = (u) => { try { return new URL(u).hostname.toLowerCase(); } catch { return ''; } };
const caText = (s, n) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, n);

// One row per reported attack, newest addition first. Kept: the victim as ransomware.live names it, the settled
// country with its basis and the raw code, the attack and listing dates, the article (title, URL, outlet), the group
// that claimed it on a leak site if ransomware.live matched one, and the ransomware.live record. Dropped: the victim
// domain (only its country is kept), the French summaries and the infostealer exposure counts.
export function normalizeCyberattacks(arr) {
  const seen = new Set(), rows = [];
  for (const a of Array.isArray(arr) ? arr : []) {
    if (!a || typeof a !== 'object') continue;
    const url = /^https?:\/\//i.test(String(a.url || '')) ? String(a.url) : '';
    const outlet = caHost(url), vhost = String(a.domain || '').trim().toLowerCase();
    const key = [vhost || caText(a.victim, 160), caDay(a.date), url].join('|');
    if (seen.has(key)) continue;
    seen.add(key);
    const p = placeCyberattack(a.country, vhost, outlet, a.title);
    const link = String(a.link || '');
    rows.push({
      victim: caText(a.victim, 160) || vhost, cc: p.cc, cc_basis: p.basis, cc_feed: caText(a.country, 4).toUpperCase(),
      ...(p.candidates && p.candidates.length ? { cc_candidates: p.candidates } : {}),
      cc_domain: ccOfHost(vhost), cc_outlet: ccOfHost(outlet),
      date: caDay(a.date), added: caDay(a.added), title: caText(a.title, 240), url, outlet: outlet.replace(/^www\./, ''),
      claimed_by: typeof a.claim_gang === 'string' ? caText(a.claim_gang, 60).toLowerCase() : '',
      link: /^https:\/\/www\.ransomware\.live\/id\/[A-Za-z0-9+/=_-]+$/.test(link) ? link : '',
    });
  }
  rows.sort((x, y) => y.added.localeCompare(x.added) || y.date.localeCompare(x.date));
  return rows;
}

export function cyberattackDoc(arr, generated = new Date().toISOString()) {
  const rows = normalizeCyberattacks(arr);
  const by_basis = {};
  for (const r of rows) by_basis[r.cc_basis] = (by_basis[r.cc_basis] || 0) + 1;
  const placed = rows.filter((r) => r.cc).length;
  return { source: 'ransomware.live', type: 'recentcyberattacks', generated, count: rows.length, placed, unplaced: rows.length - placed,
    recoded: rows.filter((r) => r.cc && r.cc !== r.cc_feed).length, by_basis, rows };
}

